SELECT ticket_comment_id, author_employee_id, content, created_at FROM ticket_comment
WHERE company_id = #{companyId} AND it_ticket_id = #{id}
ORDER BY created_at, ticket_comment_id

mapper.sql:
WITH admin_tickets AS ( SELECT it_ticket_id AS id, requester_employee_id AS requester_id, assignee_employee_id AS assignee_id, branch_id, ticket_type AS type, status_code AS status, title, created_at AS at, CASE WHEN status_code = #{received} AND assignee_employee_id IS NULL THEN 1 ELSE 0 END AS is_unassigned, CASE WHEN assignee_employee_id = #{employeeId} AND status_code NOT IN (#{closed}, #{canceled}, #{rejected}) THEN 1 ELSE 0 END AS is_mine, CASE WHEN status_code = #{inProgress} THEN 1 ELSE 0 END AS is_in_progress, CASE WHEN status_code = #{resolved} THEN 1 ELSE 0 END AS is_resolved FROM it_ticket WHERE company_id = #{companyId}
AND INSTR(LOWER(title), LOWER(#{keyword})) > 0
)

